var n=`1025-goi-cuon`;var r=`world-1025`;var t=`VN`;var s=`southeast-asia`;var o=4;var a=29;var l={en:`Goi Cuon`,ua:`Гой куон`};var u={en:`Goi Cuon is a dish from Vietnam prepared with rice vermicelli, shrimp, pork loin, rice paper wrappers. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Гой куон, страва кухні країни В'єтнам, яку готують із таких продуктів: рисова вермішель, креветка, свиняча корейка, рисовий папір. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Cook the listed ingredients in simmering water for about 5 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 5 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:5,i:[[`rice-vermicelli`,270,`g`],[`water`,950,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 7 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 7 хвилин до готовності й м’якості.`,t:[`poaching`],m:7,i:[[`shrimp`,350,`g`],[`pork-loin`,270,`g`]]},{en:`Moisten the rice paper sheets briefly, then roll with the COOKED shrimp and pork, rice vermicelli, cucumber, lettuce and herbs; no raw protein goes in the rolls.`,ua:`Коротко змочіть рисовий папір і загорніть із ГОТОВИМИ креветками, свининою, рисовою локшиною, огірком, салатом та зеленню; сирих білкових продуктів не додавайте.`,t:[`rolling-stuffed-food`],m:12,i:[[`rice-paper-wrappers`,12,`pcs`],[`lettuce`,170,`g`],[`mint`,30,`g`],[`cucumber`,180,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`hoisin-sauce`,110,`g`],[`peanut-butter`,65,`g`],[`lime-juice`,25,`ml`]]}];var d={slug:n,id:r,country:`VN`,region:s,servings:4,minutes:29,title:l,text:u,steps:m};export{t as country,d as default,r as id,a as minutes,s as region,o as servings,n as slug,m as steps,u as text,l as title};